function Icon({name,size=18,className=''}:{name:string;size?:number;className?:string}){return <svg className={className} width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{iconPaths[name]||iconPaths.code}</svg>}
function Brand({small=false}:{small?:boolean}){return <ReferenceBrand small={small}/>}
function Highlight({code}:{code:string}){
 const tokens=code.split(/("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|\b(?:def|return|if|else|function|const|let|var|import|from|for|while|class|new|async|await|print|console|true|false|None|in)\b|\b\d+\b|#[^\n]*|\/\/[^\n]*)/g);
 return <>{tokens.map((t,i)=><span key={i} className={/^['"]/.test(t)?'syntax-string':/^#|^\/\//.test(t)?'syntax-comment':/^\d/.test(t)?'syntax-number':/^(def|return|if|else|function|const|let|var|import|from|for|while|class|new|async|await|in)$/.test(t)?'syntax-keyword':/^(print|console)$/.test(t)?'syntax-function':''}>{t}</span>)}</>
}
function MiniEditor({language,code,file,output=false}:{language:string;code:string;file:string;output?:boolean}){return <div className={`mini-editor ${output?'is-output':''}`}><div className="mini-editor-head"><span className={`lang-dot ${language.toLowerCase()}`}/><span>{file}</span><span className="mini-language">{language}</span></div><div className="mini-code"><div className="line-numbers">{code.split('\n').map((_,i)=><span key={i}>{i+1}</span>)}</div><pre><Highlight code={code}/></pre></div></div>}
function Accordion({items=faqs}:{items?:typeof faqs}){const [open,setOpen]=useState<number|null>(0);return <div className="accordions">{items.map((item,i)=><div className={`accordion ${open===i?'open':''}`} key={item.q}><button aria-expanded={open===i} onClick={()=>setOpen(open===i?null:i)}>{item.q}<Icon name={open===i?'close':'plus'} size={19}/></button>{open===i&&<p>{item.a}</p>}</div>)}</div>}

